window.kbPageData["views/entry/k-f6786866c10fd4e5"] = {"key":"entry/k-f6786866c10fd4e5","state":{"route":"entry/k-f6786866c10fd4e5"},"node":{"id":"k-f6786866c10fd4e5","mode":"k","title":"雨污分流","type":"原理与机制","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["末端截污遇暴雨失效时可从源头实施雨污分流"],"qs":["国考 2025 地市级 申论#2"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"雨污分流是在排水源头采用分开的管网输送雨水和污水，从而减轻雨水进入污水管道和截污设施造成的负荷。","review":{"definition":"雨污分流是在排水源头采用分开的管网输送雨水和污水，从而减轻雨水进入污水管道和截污设施造成的负荷。","explanation":"万仑河原先采用末端截污，专家实地调研发现，暴雨时管道截不住污水。虑远科技参与研讨并综合专家意见，提出从源头实行雨污分流，埠西区政府再次组织专家论证后决定实施改造。这一过程体现了本题中企业提案、政府论证并组织实施的协作方式。","references":[],"evidence":"建议从源头抓起，实现雨污分流","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 地市级 申论#2":{"paper":"国考 2025 地市级 申论","n":2,"mod":"申论","src":["16fbc0b81d8aafc9f70b.pdf",4],"asrc":["cfcf70b08272c4dfe4c2.pdf",1],"card":"52d38b248b37fe901fd73382","links":[{"id":"k-f6786866c10fd4e5","role":"直接考查","why":"暴雨时末端管道截不住污水，企业综合专家意见提出源头治理方案，政府论证后实施。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f6786866c10fd4e5":[["国考 2025 地市级 申论#2"]]}};
